"use strict";(self.webpackChunkcddl_codegen_documentation=self.webpackChunkcddl_codegen_documentation||[]).push([[684],{8635:(e,t,s)=>{s.r(t),s.d(t,{assets:()=>c,contentTitle:()=>r,default:()=>u,frontMatter:()=>a,metadata:()=>o,toc:()=>d});var n=s(5893),i=s(1151);const a={},r="TransactionBuilder",o={id:"modules/builders/index",title:"TransactionBuilder",description:"In order to simplify transaction creation, we provide a TransactionBuilder struct that manages witnesses, fee calculation, change addresses and such. Assume we have instantiated an instance under the variable builder for this explanation. The TransactionBuilder requires several protocol parameters governing Cardano to be created which is shown in the following section. These are specified initially in the genesis file for Cardano nodes.",source:"@site/docs/modules/builders/index.mdx",sourceDirName:"modules/builders",slug:"/modules/builders/",permalink:"/cardano-multiplatform-lib/modules/builders/",draft:!1,unlisted:!1,tags:[],version:"current",frontMatter:{},sidebar:"tutorialSidebar",previous:{title:"generating_transactions",permalink:"/cardano-multiplatform-lib/modules/builders/generating_transactions"},next:{title:"CIP36",permalink:"/cardano-multiplatform-lib/modules/cip36"}},c={},d=[];function l(e){const t={a:"a",code:"code",h1:"h1",p:"p",pre:"pre",...(0,i.a)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.h1,{id:"transactionbuilder",children:"TransactionBuilder"}),"\n",(0,n.jsxs)(t.p,{children:["In order to simplify transaction creation, we provide a ",(0,n.jsx)(t.code,{children:"TransactionBuilder"})," struct that manages witnesses, fee calculation, change addresses and such. Assume we have instantiated an instance under the variable ",(0,n.jsx)(t.code,{children:"builder"})," for this explanation. The ",(0,n.jsx)(t.code,{children:"TransactionBuilder"})," requires several protocol parameters governing Cardano to be created which is shown in the following section. These are specified initially in the genesis file for Cardano nodes."]}),"\n",(0,n.jsxs)(t.p,{children:["The minimum required for a valid transaction is to add inputs, outputs, and either set the fee explicitly with ",(0,n.jsx)(t.code,{children:"builder.set_fee(fee)"}),", or calculate it implicitly using ",(0,n.jsx)(t.code,{children:"builder.add_change_if_needed(address)"}),".\nOptionally a transaction can also have certificates, reward withdrawals, metadata, and minting added to it.\nAny change made to the builder can impact the size and thus the fee so the fee should be the last thing set.\nIf implicitly setting the fee any extra ADA (",(0,n.jsx)(t.code,{children:"inputs + withdrawals - outputs + refund - deposit - min fee"}),") is sent to the provided change address.\nFees must be sufficient, i.e. ",(0,n.jsx)(t.code,{children:"inputs + withdrawals + refund >= outputs + deposit + fee"})," which must be manually ensured if you explicitly set the fee. Any extra fee is not necessary and the extra ADA beyond that will be burned.\nOnce the transaction is ready, ",(0,n.jsx)(t.code,{children:"const body = builder.build()"})," can be called to return a ready ",(0,n.jsx)(t.code,{children:"TransactionBody"}),"."]}),"\n",(0,n.jsx)(t.p,{children:"Withdrawals are ADA withdrawn as part of the rewards generated by staking and deposits are refundable ADA locked while resources such as stake certificates or pool registrations exist on the blockchain. They are returned as refunds when these resources are deregistered/retired."}),"\n",(0,n.jsxs)(t.p,{children:["To get to a transaction ready to post on the blockchain, we must create a ",(0,n.jsx)(t.code,{children:"Transaction"})," from that, which consists of the ",(0,n.jsx)(t.code,{children:"TransactionBody"}),", a matching ",(0,n.jsx)(t.code,{children:"TransactionWitnessSet"})," and optionally an ",(0,n.jsx)(t.code,{children:"AuxiliaryData"}),".\nThe witnesses and optional metadata must match those provided to the builder. The witnesses must sign the hash of the transaction body returned by ",(0,n.jsx)(t.code,{children:"hash_transaction(body)"}),". In addition to the witnesses for inputs, withdrawals and some certificates require witnesses as well. For example, staking address registration does not require a witness while stake address de-registration requires one. For any questions or doubts about the rules governing fees, deposits, rewards, certificates or which witness types are required refer to the ",(0,n.jsx)(t.a,{href:"https://github.com/input-output-hk/cardano-ledger-specs#cardano-ledger",children:"specs for the relevant era"}),", specifically the Shelley design specification for general design for non-governance certificates. Refer to the Conway specs for those. The formal specification could be useful for specific details as well. The design spec contains details about which certificates require which type of witnesses in the Certificates and Registrations section."]}),"\n",(0,n.jsx)(t.h1,{id:"transactionbuilderconfig",children:"TransactionBuilderConfig"}),"\n",(0,n.jsxs)(t.p,{children:["To correctly make transactions the builder must know some on-chain parameters such as the current fee costs, key deposits, etc. These can all potentially change, even if some have largely been static for large periods of time. We pass these into the builder via the ",(0,n.jsx)(t.code,{children:"TransactionBuilderConfigBuilder"}),". For test things out hard-coding them might suffice, but these parameters should ideally be fetched from the current blockchain head or your transactions could fail to be accepted by the network or will end up paying higher fees. The cost models parameter is optional if you are not building a transaction that utilizes Plutus smart contracts."]}),"\n",(0,n.jsxs)(t.p,{children:["Code examples for the builders will assume you have a ",(0,n.jsx)(t.code,{children:"make_tx_builder()"})," function that creates a ",(0,n.jsx)(t.code,{children:"TransactionBuilder"})," with the appropriate config."]}),"\n",(0,n.jsx)(t.h1,{id:"blockfrost",children:"Blockfrost"}),"\n",(0,n.jsxs)(t.p,{children:["One way of getting this information is via the ",(0,n.jsx)(t.code,{children:"epochs/latest/parameters"})," endpoint of blockfrost. This can be automated from rust using the ",(0,n.jsx)(t.code,{children:"cml-blockfrost"})," crate's ",(0,n.jsx)(t.code,{children:"make_tx_builder_cfg()"}),". Blockfrost is by no means necessary but it can be convenient. It is possible to get this information by other means as well e.g. having a synced cardano node."]}),"\n",(0,n.jsxs)(t.p,{children:["Using ",(0,n.jsx)(t.code,{children:"cml-blockfrost"})," (rust):"]}),"\n",(0,n.jsx)(t.pre,{children:(0,n.jsx)(t.code,{className:"language-rust",children:"let cfg = cml_blockfrost::make_tx_builder_cfg(&api).await.unwrap();\nlet mut tx_builder = TransactionBuilder::new(cfg);\n"})}),"\n",(0,n.jsxs)(t.p,{children:["This could also be done manually similar to below (or reference ",(0,n.jsx)(t.code,{children:"cml-blockfrost"}),"'s code)"]}),"\n",(0,n.jsx)(t.p,{children:"Manually using WASM:"}),"\n",(0,n.jsx)(t.pre,{children:(0,n.jsx)(t.code,{className:"language-javascript",children:"let params = await blockfrost.epochsLatestParameters();\n\n// cost order is based on lex ordering of keys\nlet costModels = CML.CostModels.new();\nlet v1Costs = params.cost_models['PlutusV1'];\nif (v1Costs != null) {\n    let v1CMLCosts = CML.IntList.new();\n    for (key in Object.keys(v1Costs).toSorted()) {\n        v1CMLCosts.add(CML.Int.new(v1Costs[key]));\n    }\n    costModels.set_plutus_v1(v1CMLCosts);\n}\n// cost order is based on lex ordering of keys\nlet v2Costs = params.cost_models['PlutusV2'];\nif (v2Costs != null) {\n    let v2CMLCosts = CML.IntList.new();\n    for (key in Object.keys(v2Costs).toSorted()) {\n        v2CMLCosts.add(CML.Int.new(v2Costs[key]));\n    }\n    costModels.set_plutus_v2(v2CMLCosts);\n}\n// note: as of writing this the sancho testnet format is different for v3\n// compared to v1/v2. this may remain true once mainnet switches over so\n// please inspect the object you are getting for cost models from blockfrost\n\nlet configBuilder = CML.TransactionBuilderConfigBuilder.new()\n    .fee_algo(CML.LinearFee.new(params.min_fee_a, params.min_fee_b))\n    .coins_per_utxo_byte(BigNum(params.coins_per_utxo_size))\n    .pool_deposit(BigNum(params.pool_deposit))\n    .key_deposit(BigNum(params.key_deposit))\n    .max_value_size(Number(params.max_val_size))\n    .max_tx_size(params.max_tx_size)\n    .ex_unit_prices(CML.ExUnitPrices.new(\n        CML.SubCoin.from_base10_f32(params.price_mem),\n        CML.SubCoin.from_base10_f32(params.price_step)\n    ))\n    .cost_models(costModels)\n    .collateral_percentage(params.collateral_percent)\n    max_collateral_inputs(params.max_collateral_inputs);\nlet mut txBuilder = CML.TransactionBuilder.new(configBuilder.build());\n"})})]})}function u(e={}){const{wrapper:t}={...(0,i.a)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}},1151:(e,t,s)=>{s.d(t,{Z:()=>o,a:()=>r});var n=s(7294);const i={},a=n.createContext(i);function r(e){const t=n.useContext(a);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),n.createElement(a.Provider,{value:t},e.children)}}}]);